"""Replay the module sources frozen in an issue #644 comparison artifact.

Run from a Plenty checkout: python3 replay.py ARTIFACT COMPILER OUTPUT.
The existing examples/http_server_bench.py supplies workload generation.
"""
import hashlib,importlib.util,json,os,pathlib,platform,statistics,subprocess,sys
artifact=pathlib.Path(sys.argv[1]); compiler=pathlib.Path(sys.argv[2]).resolve(); output=pathlib.Path(sys.argv[3]).resolve(); output.mkdir(parents=True,exist_ok=True)
root=pathlib.Path.cwd(); spec=importlib.util.spec_from_file_location('bench',root/'examples/http_server_bench.py');bench=importlib.util.module_from_spec(spec);spec.loader.exec_module(bench)
data=json.loads(artifact.read_text()); sources=data['sources']; variants=['before','after']; executables={}
for variant in variants:
 folder=output/variant;folder.mkdir(exist_ok=True)
 (folder/'main.plenty').write_text(sources['main'])
 (folder/'server.plenty').write_text(sources[variant])
 exe=folder/'server';executables[variant]=exe
 subprocess.run([str(compiler),'--release','--compile',str(folder/'main.plenty'),'-o',str(exe)],check=True,env={**os.environ,'PLENTY_CACHE':'off'})
load_before=os.getloadavg()
results={v:[] for v in variants}
for name,path,keep,concurrency,_,body in bench.WORKLOADS:
 samples={v:[] for v in variants}
 for iteration in range(3):
  for v in variants:
   scratch=output/v;exe=executables[v]
   with bench.Server(exe,{'CAPACITY':'256'},False,'0') as server:
    result=bench.run_ab(server.port,False,path,keep,concurrency,5000,body,scratch,'8,10,12,14')
    fields=bench.status_fields(server.process.pid)
    result['peak_rss_kib']=int(fields['VmHWM'].split()[0]);result['threads']=int(fields['Threads']);result['cpu_seconds']=bench.cpu_seconds(server.process.pid)
    result['report']=server.stop()
    assert result['completed']==5000 and result['failed']==result['missing']==result['non_2xx']==0,result
    assert 'requests 5001 rejected 0' in result['report'],result
    samples[v].append(result)
 for v in variants:
  summary={'name':name,'concurrency':concurrency,'path':path,'keep_alive':keep,'requests':5000,'body':body,'runs':samples[v]}
  for key in ['rps','p50_ms','p99_ms']:summary[key+'_median']=statistics.median(s[key] for s in samples[v])
  results[v].append(summary)
  print(v,name,summary['rps_median'],summary['p99_ms_median'],flush=True)
idle={v:bench.idle_memory(executables[v],984,False,{'CAPACITY':'256'},'0') for v in variants}
machine=bench.describe(str(compiler),False,output/'after/main.plenty','0','8,10,12,14');machine['load_before']=load_before;machine['load_after']=os.getloadavg()
result={'baseline_revision':data['baseline_revision'],'machine':machine,'method':'Same compiler/runtime; both module snapshots imported as local server with identical benchmark fixture. Three before/after alternating rounds per workload; Stats include /stop and final draining. No task-local builds during measurement; unrelated shared-host activity was not controlled.','native_sha256':{v:hashlib.sha256(executables[v].read_bytes()).hexdigest() for v in variants},'sources':sources,'source_sha256':{k:hashlib.sha256(v.encode()).hexdigest() for k,v in sources.items()},'results':results,'idle':idle,'reproduction_script':pathlib.Path(__file__).read_text()}
(output/'results.json').write_text(json.dumps(result,indent=2)+'\n')
